// C++17
#include <iostream>

template<typename T>               // T is a type parameter
T midpoint(T bid, T ask) {
    return bid + (ask - bid) / 2;
}

int main() {
    std::cout << midpoint(99, 101) << "\n";       // T = int    -> 100
    std::cout << midpoint(99.0, 101.0) << "\n";   // T = double -> 100
    // midpoint(99, 100.5);  // compile error: T deduced as int AND double
}

// C++17
#include <cstddef>
#include <iostream>

template<typename T, std::size_t N>   // N is a non-type parameter
class FixedVec {
public:
    void push(T x) { data_[n_++] = x; }
    T total() const {
        T sum{};
        for (std::size_t i = 0; i < n_; ++i) sum += data_[i];
        return sum;
    }
private:
    T data_[N]{};
    std::size_t n_ = 0;
};

int main() {
    FixedVec<double, 4> px;                     // concrete type FixedVec<double,4>
    px.push(10.5); px.push(11.25); px.push(9.75); px.push(10.0);
    std::cout << px.total() << "\n";            // 41.5
    std::cout << sizeof(FixedVec<double, 4>) << "\n"; // 40 = 4 doubles + count
    std::cout << sizeof(FixedVec<double, 8>) << "\n"; // 72 = 8 doubles + count
}

// C++17 - class template argument deduction (CTAD)
#include <iostream>
#include <utility>
#include <vector>

int main() {
    std::pair px(1, 2.5);          // std::pair<int, double>, no make_pair
    std::vector qx{10.5, 11.25};   // std::vector<double>
    std::cout << px.first << " " << qx[0] << "\n";   // 1 10.5
}

guidedExercise.solution:
```cpp
// C++17
template<typename T>
T total(const std::vector<T>& v) {
    T sum{};
    for (const T& x : v) sum += x;
    return sum;
}
```

For the first call the compiler deduces `T = double` and generates `total<double>`: $10.5 + 11.25 + 9.75 + 10.0 = 41.5$. For the second it deduces `T = int` and generates a separate `total<int>`: $200 + 300 - 50 = 450$. **Two independent functions** were generated at two call sites; if `total` is never called for a third type, no code for it exists.

`T sum{}` zero-initialises whatever T is, so the template works for any type that is default-constructible and supports `+=`. The tempting `T sum = 0;` would fail to compile for types without a constructor from `int` - `T{}` is the general form.

